import {
  CreateDateColumn,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
} from 'typeorm';

/**
 * Common columns for every table (SPEC.md §7).
 * `id` is generated by PostgreSQL with gen_random_uuid() (built in since PG 13; selected via
 * `uuidExtension: 'pgcrypto'` in the DataSource options). Timestamps are timestamptz (UTC).
 * Not to be confused with TypeORM's own active-record `BaseEntity`, which we do not use.
 */
export abstract class BaseEntity {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @CreateDateColumn({ type: 'timestamptz' })
  createdAt!: Date;

  @UpdateDateColumn({ type: 'timestamptz' })
  updatedAt!: Date;
}
